"""Third opinion: the bid rules written straight from the rule text, on the neutral scenario form.

Independent of both calculators on purpose: exact rational arithmetic (fractions.Fraction) instead of Decimal, integer
carton arithmetic, numeric-aware ordering of position identifiers. Where the given evidence does not determine a
field, the field is UNDET (a wildcard in comparisons) instead of a guess.
"""
from __future__ import annotations

from decimal import Decimal
from fractions import Fraction

UNDET = "UNDET"
KINDS = ("condition_group", "packaging_tariff", "delivery_commitment", "setup_pool", "project_bonus")
ATTR = {"stroke": "stroke", "hub": "stroke", "stellweg": "stroke", "bore": "bore", "bohrung": "bore",
        "pressure": "pressure", "druck": "pressure", "nenndruck": "pressure", "mounting": "mounting",
        "befestigung": "mounting", "certification": "cert", "zertifizierung": "cert"}
NUMERIC = ("stroke", "bore", "pressure")


def idkey(value):
    """Ascending identifier order: numbers by value ("9" before "10"), anything else as text."""
    text = str(value).strip()
    return (0, int(text), text) if text.isdigit() else (1, 0, text)


def cents_half_up(x: Fraction) -> int:
    negative, n = x < 0, abs(x) * 100
    q, r = divmod(n.numerator, n.denominator)
    if 2 * r >= n.denominator:
        q += 1
    return -q if negative else q


def money(x) -> Decimal:
    return (Decimal(cents_half_up(Fraction(x))) / Decimal(100)).quantize(Decimal("0.01"))


def norm_txt(value) -> str:
    return " ".join(str(value or "").split()).casefold()


NOCERT = {"", "-", "—", "keine", "keine gefordert", "nicht gefordert", "ohne", "none"}


def norm_cert(value) -> str:
    text = norm_txt(value)
    return "" if text in NOCERT else text


def german_int(value) -> int:
    if isinstance(value, int):
        return value
    digits = "".join(ch for ch in str(value).split(",")[0] if ch.isdigit())
    return int(digits)


def live_answers(scn, withdraw_mode="flat"):
    dated = sorted((a for a in scn["qa"] if a["when"] <= scn["t0"]), key=lambda a: (a["when"], idkey(a["num"])))
    withdrawn: set[str] = set()
    if withdraw_mode == "flat":  # any in-date answer withdraws what it names
        withdrawn = {str(w).strip() for a in dated for w in a["withdraws"]}
    else:  # "chain": only a surviving answer withdraws, and only an EARLIER answer
        for i in range(len(dated) - 1, -1, -1):
            if dated[i]["num"] in withdrawn:
                continue
            earlier = {b["num"] for b in dated[:i]}
            withdrawn |= {str(w).strip() for w in dated[i]["withdraws"] if str(w).strip() in earlier}
    return dated, [a for a in dated if a["num"].strip() not in withdrawn]


def resolve_reqs(scn, answers):
    out = {ref: dict(r) for ref, r in scn["reqs"].items()}
    for a in answers:  # oldest first: the latest wins per attribute
        for rev, ref, attr, val in a["amend"]:
            if norm_txt(rev) != norm_txt(scn["gov"]) or ref not in out:
                continue
            name = ATTR.get(str(attr).strip().lower())
            if name is None:
                continue
            out[ref][name] = german_int(val) if name in NUMERIC else str(val).strip()
    state = {}
    for ref, r in out.items():
        if r.get("usable"):
            entry = scn["auth"]["reserves"].get(r.get("reserve_key"))
            if entry is None or (entry[0] is not None and norm_txt(entry[0]) != norm_txt(scn["gov"])):
                state[ref] = "reserve"
            else:
                r["stroke"] = r["stroke"] + 2 * entry[1]
    return out, state


def final_qty(scn, answers, reqs):
    cur = {p["id"]: (p["qty"], p["unit"]) for p in scn["positions"]}
    for a in answers:
        for pos, q, unit in a["qty"]:
            if pos in cur:
                cur[pos] = (q, unit or cur[pos][1])
    out = {}
    for p in scn["positions"]:
        q, unit = cur[p["id"]]
        if unit == "Satz":
            pps = (reqs.get(p["req"]) or {}).get("pps")
            if not pps:
                out[p["id"]] = None
                continue
            q *= pps
        out[p["id"]] = q
    return out


def same_attrs(m, r) -> bool:
    return (m["bore"] == r["bore"] and m["stroke"] == r["stroke"] and m["pressure"] == r["pressure"]
            and norm_txt(m["mounting"]) == norm_txt(r["mounting"]) and norm_cert(m["cert"]) == norm_cert(r["cert"]))


def match(req, mats):
    exact = [m for m in mats if m["active"] and same_attrs(m, req)]
    grouped = [m for m in exact if norm_txt(m["group"]) == norm_txt(req["group"])]
    return (grouped or exact or [None])[0]


def base_price(m, q, scn):
    valid = [c for c in m["conds"] if c["from"] <= scn["t0"] <= c["to"]]
    if not valid:
        return None, "no_valid_condition"
    c = valid[0]
    reached = [s for s in c["scales"] if s[0] <= q]
    if not reached:
        return None, "below_lowest_scale"
    price = Fraction(max(reached, key=lambda s: s[0])[1]) / c["pu"]
    if c["cur"].upper() != "EUR":
        rate = scn["auth"]["fx"].get(c["fx"])
        if rate is None:
            return None, "fx_missing"
        price *= Fraction(rate)
    return money(price), None


def merge_assign(answers):
    keys: dict[str, dict[str, str]] = {}
    fees: dict[str, Decimal] = {}
    for a in answers:
        for pos, kinds in a["assign"].items():
            keys.setdefault(pos, {}).update(kinds)
        fees.update(a["fees"])
    return keys, fees


def prelim(scn, withdraw_mode="flat", withdraw_scope="all"):
    dated, live = live_answers(scn, withdraw_mode)
    others = live if withdraw_scope == "all" else dated  # "quantity_only": a withdrawal voids only the quantity change
    reqs, rstate = resolve_reqs(scn, others)
    qty = final_qty(scn, live, reqs)
    assign, fees = merge_assign(others)
    state, mat, base, why = {}, {}, {}, {}
    for p in scn["positions"]:
        pid = p["id"]
        r = reqs.get(p["req"])
        state[pid] = "no_req" if r is None else rstate.get(p["req"], "ok")
        mat[pid] = match(r, scn["mats"]) if state[pid] == "ok" else None
        base[pid], why[pid] = (None, None)
        if mat[pid] is not None and qty[pid] is not None:
            base[pid], why[pid] = base_price(mat[pid], qty[pid], scn)
    return {"live": live, "reqs": reqs, "qty": qty, "assign": assign, "fees": fees, "state": state, "mat": mat,
            "base": base, "why": why}


def allocate(total_cents: int, weights: dict[str, Fraction], method: str) -> dict[str, int]:
    keys = sorted(weights, key=idkey)
    total_weight = sum(weights.values(), Fraction(0))
    if total_cents <= 0 or total_weight <= 0:
        return {k: 0 for k in keys}
    exact = {k: Fraction(total_cents) * weights[k] / total_weight for k in keys}
    floor = {k: exact[k].numerator // exact[k].denominator for k in keys}
    left = total_cents - sum(floor.values())
    if method == "remainder_to_first":
        floor[keys[0]] += left
    elif method == "remainder_to_last":
        floor[keys[-1]] += left
    elif method == "remainder_to_largest":
        floor[max(keys, key=lambda k: (weights[k], -keys.index(k)))] += left
    else:
        for k in sorted(keys, key=lambda k: (-(exact[k] - floor[k]), idkey(k)))[:left]:
            floor[k] += 1
    return floor


def solve(scn, withdraw_mode="flat", withdraw_scope="all"):
    P = prelim(scn, withdraw_mode, withdraw_scope)
    auth = scn["auth"]
    ids = [p["id"] for p in scn["positions"]]
    approved = auth["disc"] or Decimal(0)

    if any(P["state"][pid] == "ok" and P["mat"][pid] is None for pid in ids):
        return {"error": None, "decision": "no_bid", "discount": Decimal(0) if auth["min_order"] is not None else approved,
                "total": Decimal("0.00"), "lines": {}, "omitted": {}, "prelim": P}

    known = [pid for pid in ids if P["mat"][pid] is not None and P["qty"][pid] is not None]
    priced = [pid for pid in known if P["base"][pid] is not None]
    omitted = {pid: (P["why"][pid] or ("set_size" if P["mat"][pid] is not None else P["state"][pid]))
               for pid in ids if pid not in priced}
    goods = {pid: Fraction(P["qty"][pid]) * Fraction(P["base"][pid]) for pid in priced}

    discount = approved
    if approved and auth["min_order"] is not None:
        reached = money(sum(goods.values(), Fraction(0))) >= auth["min_order"]
        discount = approved if reached else (Decimal(0) if len(priced) == len(ids) else UNDET)

    demand: dict[str, int] = {}
    for pid in known:  # every position that selects the material, priced or not
        demand[P["mat"][pid]["num"]] = demand.get(P["mat"][pid]["num"], 0) + P["qty"][pid]

    def assigned(pid, kind):
        return P["assign"].get(pid, {}).get(kind) or None

    pool_share: dict[str, object] = {}
    for key, (fee, method) in auth["pools"].items():
        members = [pid for pid in ids if assigned(pid, "setup_pool") == key]
        if not members:
            continue
        weights = {pid: Fraction(P["qty"][pid]) * Fraction(P["mat"][pid]["alloc_g"] or 0) for pid in members if pid in known}
        if len(weights) < len(members) or sum(weights.values(), Fraction(0)) <= 0:
            pool_share.update({pid: UNDET for pid in members})
            continue
        shares = allocate(cents_half_up(Fraction(fee)), weights, method)
        pool_share.update({pid: Fraction(shares[pid], 100) for pid in members})

    rebate: dict[str, object] = {}
    for key, bands in auth["bonus"].items():
        members = [pid for pid in ids if assigned(pid, "project_bonus") == key]
        if not members:
            continue
        if any(pid not in priced for pid in members):
            rebate.update({pid: UNDET for pid in members})
            continue
        eligible = sum((goods[pid] for pid in members), Fraction(0))
        credit = Fraction(0)
        for lower, upper, percent in bands:
            top = eligible if upper is None else min(eligible, Fraction(upper))
            if top > Fraction(lower):
                credit += (top - Fraction(lower)) * Fraction(percent) / 100
        shares = allocate(cents_half_up(credit), {pid: goods[pid] for pid in members}, "largest_remainder")
        rebate.update({pid: Fraction(shares[pid], 100) for pid in members})

    lines = {}
    for pid in priced:
        m, q = P["mat"][pid], P["qty"][pid]
        base = Fraction(P["base"][pid])

        if m["index"]:
            rate = auth["index_kg"].get(m["index"])
            mass = UNDET if rate is None else Fraction(m["sur_g"] or 0) / 1000 * Fraction(rate)
        else:
            mass = Fraction(0)

        pool_key = assigned(pid, "setup_pool")
        pool = Fraction(0) if pool_key is None else pool_share.get(pid, UNDET)
        setup = UNDET if pool is UNDET else Fraction(P["fees"].get(pid, 0)) + pool

        tariff_key = assigned(pid, "packaging_tariff")
        if tariff_key is None:
            cartons = Fraction(0)
        elif tariff_key not in auth["tariffs"] or not m["carton"]:
            cartons = UNDET
        else:
            cartons = Fraction(-(-q // m["carton"])) * Fraction(auth["tariffs"][tariff_key])

        bonus_key = assigned(pid, "project_bonus")
        credit = Fraction(0) if bonus_key is None else rebate.get(pid, UNDET)

        group = assigned(pid, "condition_group")
        clause = "base_only" if group is None else auth["clauses"].get(group, UNDET)

        parts = [mass, setup, cartons, credit, clause]
        if clause in ("base_only", "base_and_surcharge") and discount is UNDET:
            parts.append(UNDET)
        if any(part is UNDET for part in parts):
            unit_price = UNDET
        else:
            factor = (100 - Fraction(discount)) / 100
            unit_price = money(base * (factor if clause in ("base_only", "base_and_surcharge") else 1)
                               + mass * (factor if clause == "base_and_surcharge" else 1)
                               + (setup + cartons - credit) / q)

        pooled = demand[m["num"]]
        commitment = auth["commit"].get(assigned(pid, "delivery_commitment"))
        if commitment and str(commitment["mat"]).strip() == m["num"] and pooled <= commitment["max"]:
            lead = commitment["weeks"]
        elif m["stock"] >= pooled:
            lead = m["stock_lead"]
        else:
            lead = m["prod_lead"]

        lines[pid] = {"material": m["num"], "quantity": q, "unit_price": unit_price, "base_unit_price": P["base"][pid],
                      "surcharge_per_unit": UNDET if mass is UNDET or setup is UNDET else money(mass + setup / q),
                      "packaging_per_unit": UNDET if cartons is UNDET else money(cartons / q),
                      "rebate_total": UNDET if credit is UNDET else money(credit), "lead_time_weeks": lead}

    if any(line["unit_price"] is UNDET for line in lines.values()):
        total = UNDET
    else:
        total = money(sum((Fraction(line["quantity"]) * Fraction(line["unit_price"]) for line in lines.values()), Fraction(0)))
    return {"error": None, "decision": "bid", "discount": discount, "total": total, "lines": lines, "omitted": omitted,
            "prelim": P}

