"""Random, boundary-biased scenarios in a neutral form, and the hazards (mutations) layered on top.

A scenario is a plain dict (see `gen_clean`); every value is invented here. `gen_clean` only produces well-formed
scenarios: every position has exactly the evidence the rule text assumes. Each mutation then injects ONE deviation
(missing evidence, an edge of the representation, an ambiguity of the rule text), so a mismatch on a mutated
scenario is attributable to that mutation by construction.
"""
from __future__ import annotations

import copy
import random
from datetime import datetime, timedelta, timezone
from decimal import Decimal as D

import oracle

UTC = timezone.utc
MOUNTS = ["Flansch vorn", "Flansch hinten", "Schwenkauge", "Fussbefestigung", "Gelenkkopf", "Zapfen Mitte"]
CERTS = ["Keine gefordert", "Keine gefordert", "ATEX II 2G", "DNV", "Abnahme 3.1", "Lloyd"]
NONE_SPELLINGS = ["Keine gefordert", "Keine", "-", "", "keine", "Ohne", "Nicht gefordert"]
BORES = [32, 40, 50, 63, 80, 100, 125]
PRESSURES = [160, 210, 250, 315]
INDEX_CODES = ["MX-CU", "MX-AL", "MX-FE"]
QTYS = [1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 24, 25, 30, 40, 50, 60, 75, 100, 120, 250]
PERCENTS = ["0.5", "1", "1.25", "1.5", "2", "2.5", "3", "4"]
MICRO = timedelta(microseconds=1)


def dq(rng, lo, hi, places=2):
    scale = 10 ** places
    return D(rng.randint(int(lo * scale), int(hi * scale))) / D(scale)


def blank_answer():
    return {"num": "", "when": None, "withdraws": [], "qty": [], "amend": [], "assign": {}, "fees": {}}


def mk_conditions(rng, t0, qs, auth, serial):
    """One condition valid at t0 plus up to two that are not, in random order."""
    def one(valid):
        cur = "EUR" if rng.random() < 0.65 else rng.choice(["USD", "CHF", "GBP", "SEK"])
        fx = None
        if cur != "EUR":
            fx = f"FX-{cur}-{serial}-{rng.randint(1, 99)}"
            auth["fx"][fx] = dq(rng, 0.08, 1.4, rng.choice([4, 5, 6]))
        pu = rng.choice([1, 1, 1, 10, 100, 100, 1000])
        thresholds = {1}
        for q in qs:
            r = rng.random()
            if r < 0.45:
                thresholds.add(q)
            elif r < 0.6:
                thresholds.add(q + 1)
            elif r < 0.7 and q > 2:
                thresholds.add(q - 1)
        for _ in range(rng.randint(0, 2)):
            thresholds.add(rng.choice([5, 10, 25, 50, 100, 250, 500]))
        price = dq(rng, 20, 900, 2)
        scales = []
        for t in sorted(thresholds):
            per_piece = price
            r = rng.random()
            if r < 0.25:
                per_piece = price + D("0.005")  # an exact half cent per piece
            elif r < 0.4:
                per_piece = price + dq(rng, 0, 0.0099, 4)
            scales.append((t, per_piece * pu))
            price = (price * D(rng.randint(86, 98)) / 100).quantize(D("0.01"))
        if valid:
            start = t0 if rng.random() < 0.15 else t0 - timedelta(days=rng.randint(1, 200))
            end = t0 if rng.random() < 0.15 else t0 + timedelta(days=rng.randint(1, 200))
        elif rng.random() < 0.5:  # expired
            end = t0 - rng.choice([MICRO, timedelta(seconds=1), timedelta(days=1), timedelta(days=40)])
            start = end - timedelta(days=rng.randint(1, 200))
        else:  # not yet valid
            start = t0 + rng.choice([MICRO, timedelta(seconds=1), timedelta(days=1), timedelta(days=40)])
            end = start + timedelta(days=rng.randint(1, 200))
        return {"from": start, "to": end, "cur": cur, "fx": fx, "pu": pu, "scales": scales}

    conds = [one(True)] + [one(False) for _ in range(rng.choice([0, 0, 1, 1, 2]))]
    rng.shuffle(conds)
    return conds


def gen_clean(seed: int) -> dict:
    rng = random.Random(seed)
    t0 = datetime(2031, rng.randint(1, 12), rng.randint(1, 28), rng.choice([0, 7, 9, 12, 23]), rng.choice([0, 30, 59]),
                  tzinfo=UTC)
    gov, *other_revs = rng.sample(["A", "B", "C", "D", "E", "R2", "R3", "R4", "Index 5", "Stand 7"], 3)
    auth = {"disc": None, "min_order": None, "clauses": {}, "index_kg": {}, "reserves": {}, "tariffs": {}, "commit": {},
            "fx": {}, "pools": {}, "bonus": {}}

    n_pos = rng.randint(2, 6)
    n_req = rng.randint(1, n_pos)
    reqs = {}
    for i in range(n_req):
        r = {"bore": rng.choice(BORES), "stroke": rng.choice(range(120, 900, 20)), "pressure": rng.choice(PRESSURES),
             "mounting": rng.choice(MOUNTS), "cert": rng.choice(CERTS), "group": f"KG-{rng.randint(100, 999)}",
             "usable": False, "reserve_key": None, "pps": rng.choice([1, 2, 2, 3, 4, 6])}
        if i and rng.random() < 0.12:  # same attributes as another requirement: one material for both
            src = reqs[rng.choice(list(reqs))]
            for k in ("bore", "stroke", "pressure", "mounting", "cert"):
                r[k] = src[k]
            if rng.random() < 0.5:
                r["group"] = src["group"]
        if rng.random() < 0.3:
            r["usable"], r["reserve_key"] = True, f"ER-{i + 1}"
            auth["reserves"][r["reserve_key"]] = (gov if rng.random() < 0.7 else None, rng.randint(5, 40))
        reqs[f"AF-{i + 1:02d}"] = r
    if rng.random() < 0.3:  # a release bound to a superseded revision, under a key nobody references
        auth["reserves"]["ER-ALT"] = (other_revs[0], rng.randint(5, 40))

    style = rng.choice(["unit", "tens", "padded"])
    ids = [{"unit": str(i + 1), "tens": str((i + 1) * 10), "padded": f"{i + 1:02d}"}[style] for i in range(n_pos)]
    refs = list(reqs) + [rng.choice(list(reqs)) for _ in range(n_pos - n_req)]
    rng.shuffle(refs)
    positions = [{"id": ids[i], "req": refs[i], "qty": rng.choice(QTYS) if rng.random() < 0.7 else rng.randint(1, 300),
                  "unit": "Satz" if rng.random() < 0.3 else "Stk"} for i in range(n_pos)]
    twins: set[str] = set()
    if rng.random() < 0.25:  # two positions with identical demand: equal allocation weights, so remainders tie
        a, b = rng.sample(range(n_pos), 2)
        positions[b].update(req=positions[a]["req"], qty=positions[a]["qty"], unit=positions[a]["unit"])
        twins = {positions[a]["id"], positions[b]["id"]}
        if not any(p["req"] == refs[b] for p in positions):
            reqs.pop(refs[b], None)

    for key in ("K-11", "K-12", "K-13"):
        auth["clauses"][key] = rng.choice(["base_only", "base_and_surcharge", "none"])
    for key in ("VP-1", "VP-2"):
        auth["tariffs"][key] = dq(rng, 1.5, 45)
    for key in ("RP-1", "RP-2"):
        fee = dq(rng, 40, 900)
        if rng.random() < 0.4 and fee * 100 % 2 == 0:
            fee += D("0.01")  # an odd number of cents cannot split evenly between twins
        auth["pools"][key] = (fee, "largest_remainder")
    for code in INDEX_CODES:
        auth["index_kg"][code] = dq(rng, 1, 12, 4)

    # Assignments the Q&A hands out, spread over one to three answers.
    structured = [blank_answer() for _ in range(rng.randint(1, 3))]

    def give(pos, kind, key):
        rng.choice(structured)["assign"].setdefault(pos, {})[kind] = key

    for pid in ids:
        if rng.random() < 0.5:
            give(pid, "condition_group", rng.choice(list(auth["clauses"])))
        if rng.random() < 0.55:
            give(pid, "packaging_tariff", rng.choice(list(auth["tariffs"])))
        if rng.random() < 0.5:
            give(pid, "delivery_commitment", rng.choice(["TZ-1", "TZ-2", "TZ-3"]))
        if rng.random() < 0.3:
            fee = dq(rng, 5, 400)
            rng.choice(structured)["fees"][pid] = fee
    for kind, keys in (("setup_pool", ["RP-1", "RP-2"]), ("project_bonus", ["PB-1", "PB-2"])):
        free = list(ids)
        if rng.random() < 0.7:
            members = set(rng.sample(free, rng.randint(2, min(4, n_pos))))
            if twins and rng.random() < 0.8:
                members |= twins
            for pid in members:
                give(pid, kind, keys[0])
            free = [pid for pid in free if pid not in members]
            if free and rng.random() < 0.3:
                for pid in rng.sample(free, rng.randint(1, min(2, len(free)))):
                    give(pid, kind, keys[1])

    extras = []
    for _ in range(rng.randint(1, 6)):
        a = blank_answer()
        r = rng.random()
        if r < 0.5:
            for pid in rng.sample(ids, rng.randint(1, min(2, n_pos))):
                if pid in twins and rng.random() < 0.8:
                    continue
                unit = None if rng.random() < 0.85 else rng.choice(["Stk", "Satz"])
                a["qty"].append((pid, rng.choice(QTYS) if rng.random() < 0.7 else rng.randint(1, 300), unit))
        elif r < 0.8:
            ref = rng.choice(list(reqs))
            rev = gov if rng.random() < 0.6 else rng.choice(other_revs)
            for attr in rng.sample(["stroke", "bore", "pressure", "mounting", "certification"], rng.randint(1, 2)):
                cur = reqs[ref]
                val = {"stroke": cur["stroke"] + rng.choice([-40, -20, 20, 40, 60, 100]),
                       "bore": rng.choice([b for b in BORES if b != cur["bore"]]),
                       "pressure": rng.choice([p for p in PRESSURES if p != cur["pressure"]]),
                       "mounting": rng.choice([m for m in MOUNTS if m != cur["mounting"]]),
                       "certification": rng.choice([c for c in CERTS if c != cur["cert"]])}[attr]
                a["amend"].append((rev, ref, attr, val))
        else:  # a later answer moves one position to another key of the same kind
            pid = rng.choice(ids)
            kind = rng.choice(["condition_group", "packaging_tariff", "delivery_commitment"])
            key = rng.choice({"condition_group": list(auth["clauses"]), "packaging_tariff": list(auth["tariffs"]),
                              "delivery_commitment": ["TZ-1", "TZ-2", "TZ-3"]}[kind])
            a["assign"].setdefault(pid, {})[kind] = key
        extras.append(a)

    answers = structured + extras
    rng.shuffle(answers)
    n_future = rng.choice([0, 0, 0, 1, 1, 2]) if len(answers) > 2 else 0
    n_valid = len(answers) - n_future
    when = t0 - timedelta(days=rng.randint(3, 40))
    step = (t0 - when) / (n_valid + 1)
    for i, a in enumerate(answers):
        a["num"] = str(i + 1)
        if i < n_valid:
            when = when + step * rng.uniform(0.3, 1.0)
            a["when"] = when.replace(microsecond=0)
        else:
            gap = rng.choice([MICRO, timedelta(seconds=1), timedelta(hours=5), timedelta(days=3)]) if i == n_valid \
                else timedelta(days=rng.randint(1, 9))
            a["when"] = (t0 if i == n_valid else answers[i - 1]["when"]) + gap
        if i and rng.random() < 0.25:
            targets = [b for b in answers[:i] if b["qty"] or b["amend"]] or answers[:i]
            a["withdraws"].append(rng.choice(targets)["num"])
    if n_valid and rng.random() < 0.25:
        answers[n_valid - 1]["when"] = t0 if rng.random() < 0.7 else t0 - MICRO  # the cut-off is inclusive
    rng.shuffle(answers)

    scn = {"ref": f"TN-{rng.randint(1000, 9999)}-{rng.randint(10, 99)}", "t0": t0, "gov": gov, "positions": positions,
           "qa": answers, "reqs": reqs, "mats": [], "auth": auth, "no_material": "all", "seed": seed}

    # Materials: the one active match per final requirement, surrounded by blocked and near-miss candidates.
    final = oracle.prelim(scn)["reqs"]
    used: set[str] = set()

    def mat(attrs, group, active=True):
        while True:
            num = f"M-{rng.randint(100000, 999999)}"
            if num not in used:
                used.add(num)
                break
        cert = rng.choice(NONE_SPELLINGS) if oracle.norm_cert(attrs["cert"]) == "" else attrs["cert"]
        mounting = attrs["mounting"]
        if rng.random() < 0.2:
            mounting = rng.choice([mounting.upper(), mounting.replace(" ", "  "), " " + mounting + " "])
        return {"num": num, "active": active, "group": group, "bore": attrs["bore"], "stroke": attrs["stroke"],
                "pressure": attrs["pressure"], "mounting": mounting, "cert": cert,
                "carton": rng.choice([1, 2, 4, 6, 10, 12, 20, 24, 25, 50]),
                "alloc_g": dq(rng, 150, 9000, rng.choice([0, 1, 2])), "sur_g": dq(rng, 50, 6000, rng.choice([0, 1, 2])),
                "index": rng.choice(INDEX_CODES), "stock": 0, "stock_lead": rng.randint(1, 3),
                "prod_lead": rng.randint(4, 14), "conds": []}

    mats = []
    for ref, fr in final.items():
        exact = [m for m in mats if m["active"] and oracle.same_attrs(m, fr)]
        if not exact or (not any(m["group"] == fr["group"] for m in exact) and rng.random() < 0.5):
            mats.append(mat(fr, fr["group"]))
        raw = scn["reqs"][ref]
        if rng.random() < 0.35:
            mats.append(mat(fr, fr["group"], active=False))
        if rng.random() < 0.5:
            mats.append(mat({**fr, "stroke": fr["stroke"] + rng.choice([-10, -5, -1, 1, 5, 10])}, fr["group"]))
        if rng.random() < 0.6 and any(raw[k] != fr[k] for k in ("bore", "stroke", "pressure", "mounting", "cert")):
            mats.append(mat(raw, fr["group"]))  # what the requirement said before amendments and reserve
        if raw["usable"] and rng.random() < 0.6:
            mm = auth["reserves"][raw["reserve_key"]][1]
            mats.append(mat({**fr, "stroke": fr["stroke"] - rng.choice([mm, 2 * mm])}, fr["group"]))
        if rng.random() < 0.4:
            attr = rng.choice(["bore", "pressure", "mounting", "cert"])
            pool = {"bore": BORES, "pressure": PRESSURES, "mounting": MOUNTS, "cert": ["ATEX II 2G", "DNV", "Lloyd"]}[attr]
            other = [v for v in pool if oracle.norm_txt(v) != oracle.norm_txt(fr[attr])]
            mats.append(mat({**fr, attr: rng.choice(other)}, fr["group"]))
        if rng.random() < 0.1:
            mats.insert(0, mat(fr, fr["group"] + "-X"))  # an exact match of another catalogue group, listed first
    rng.shuffle(mats)
    scn["mats"] = mats

    P = oracle.prelim(scn)
    by_material: dict[str, list[int]] = {}
    for pid in ids:
        by_material.setdefault(P["mat"][pid]["num"], []).append(P["qty"][pid])
    for i, m in enumerate(mats):
        qs = by_material.get(m["num"], [])
        m["conds"] = mk_conditions(rng, t0, qs, auth, i)
        if qs:
            pooled = sum(qs)
            r = rng.random()
            m["stock"] = (pooled if r < 0.3 else pooled - 1 if r < 0.45 else pooled + 1 if r < 0.55
                          else max(qs) if r < 0.7 else 0 if r < 0.8 else rng.randint(0, 3 * pooled))
            if rng.random() < 0.35:
                q = rng.choice(qs)
                m["carton"] = max(1, rng.choice([q, q + 1, q - 1] + [d for d in range(2, 13) if q % d == 0]))
        else:
            m["stock"] = rng.randint(0, 500)

    P = oracle.prelim(scn)
    for key in ("TZ-1", "TZ-2", "TZ-3"):
        holders = [pid for pid in ids if P["assign"].get(pid, {}).get("delivery_commitment") == key]
        if holders and rng.random() < 0.8:
            target = P["mat"][rng.choice(holders)]["num"]
        else:
            target = rng.choice(mats)["num"]
        pooled = sum(by_material.get(target, [])) or rng.randint(1, 200)
        r = rng.random()
        ceiling = (pooled if r < 0.35 else pooled - 1 if r < 0.55 else pooled + 1 if r < 0.65
                   else max(by_material.get(target, [pooled])) if r < 0.8 else rng.randint(1, 4 * pooled))
        auth["commit"][key] = {"mat": target, "weeks": rng.randint(1, 16), "max": ceiling}

    goods = {pid: D(P["qty"][pid]) * P["base"][pid] for pid in ids}
    order_value = sum(goods.values(), D(0))
    if rng.random() < 0.85:
        auth["disc"] = D(rng.choice(["2", "2.5", "3", "4", "5", "7.5", "10", "12.5"]))
        r = rng.random()
        auth["min_order"] = (None if r < 0.35 else order_value if r < 0.6 else order_value + D("0.01") if r < 0.75
                             else order_value - D("0.01") if r < 0.85
                             else (order_value * D(rng.randint(50, 150)) / 100).quantize(D("0.01")))
    for key in ("PB-1", "PB-2"):
        eligible = sum((goods[pid] for pid in ids if P["assign"].get(pid, {}).get("project_bonus") == key), D(0))
        ref_value = eligible if eligible > 0 else D(rng.randint(500, 50000))
        cuts = set()
        for _ in range(rng.randint(1, 2)):
            r = rng.random()
            cuts.add(ref_value if r < 0.25 else ref_value - D("0.01") if r < 0.35 else ref_value + D("0.01") if r < 0.45
                     else (ref_value * D(rng.randint(10, 160)) / 100).quantize(D("0.01")))
        cuts = sorted(c for c in cuts if c > 0)
        start = D(0) if rng.random() < 0.7 else (cuts[0] * D(rng.randint(5, 60)) / 100).quantize(D("0.01"))
        edges = [start] + [c for c in cuts if c > start]
        auth["bonus"][key] = [(edges[i], edges[i + 1] if i + 1 < len(edges) else None, D(rng.choice(PERCENTS)))
                              for i in range(len(edges))]
    return scn


# ----------------------------------------------------------------------------------------------------------------
# Mutations. Each takes a deep copy of a clean scenario and returns True when it applied.
# ----------------------------------------------------------------------------------------------------------------

def _matched(scn):
    P = oracle.prelim(scn)
    return P, {pid: m for pid, m in P["mat"].items() if m is not None}


def _valid_cond(m, scn):
    return next((c for c in m["conds"] if c["from"] <= scn["t0"] <= c["to"]), None)


def m_fx_missing(scn, rng):
    """A non-EUR condition whose FX key has no fixing (another fixing exists)."""
    _, matched = _matched(scn)
    m = rng.choice(list(matched.values()))
    c = _valid_cond(m, scn)
    if c["cur"] == "EUR":
        c["cur"], c["fx"] = "USD", "FX-USD-GONE"
    scn["auth"]["fx"].pop(c["fx"], None)
    if rng.random() < 0.7:
        scn["auth"]["fx"].setdefault("FX-OTHER-1", D("0.5123"))
    return True


def m_no_index_code(scn, rng):
    """A material without a price-index code but with a surcharge mass: no mass surcharge is due."""
    _, matched = _matched(scn)
    m = rng.choice(list(matched.values()))
    m["index"] = None
    return bool(m["sur_g"])


def m_index_missing(scn, rng):
    """A material whose index code has no rate in the authorised index message."""
    _, matched = _matched(scn)
    rng.choice(list(matched.values()))["index"] = "MX-GONE"
    return True


def m_no_valid_condition(scn, rng):
    """The matched material has price conditions, none of them valid on the scenario date."""
    _, matched = _matched(scn)
    m = rng.choice(list(matched.values()))
    for c in m["conds"]:
        if c["from"] <= scn["t0"] <= c["to"]:
            c["to"] = scn["t0"] - rng.choice([MICRO, timedelta(days=2)])
            c["from"] = min(c["from"], c["to"] - timedelta(days=5))
    return True


def m_below_lowest_scale(scn, rng):
    """The final quantity is below the lowest scale of the valid condition."""
    P, matched = _matched(scn)
    pid = rng.choice(list(matched))
    q = P["qty"][pid]
    c = _valid_cond(matched[pid], scn)
    c["scales"] = [(t + q, price) for t, price in c["scales"]]
    return True


def _drop_match(scn, rng):
    P, matched = _matched(scn)
    pid = rng.choice(list(matched))
    req = P["reqs"][next(p["req"] for p in scn["positions"] if p["id"] == pid)]
    for m in scn["mats"]:
        if m["active"] and oracle.same_attrs(m, req):
            m["active"] = False if rng.random() < 0.5 else m["active"]
            if m["active"]:
                m["stroke"] += 3
    return True


def m_no_material(scn, rng):
    """One requirement has no active exact match; the caller reports it in `no_material`."""
    return _drop_match(scn, rng)


def m_no_material_unflagged(scn, rng):
    """Same, but the caller does not pass `no_material`."""
    scn["no_material"] = None
    return _drop_match(scn, rng)


def m_reserve_missing(scn, rng):
    """A usable-travel requirement whose per-end reserve was not found."""
    usable = [r for r in scn["reqs"].values() if r["usable"]]
    if not usable:
        return False
    scn["auth"]["reserves"].pop(rng.choice(usable)["reserve_key"], None)
    return True


def m_reserve_wrong_revision(scn, rng):
    """A usable-travel requirement whose only reserve release is bound to a superseded revision."""
    usable = [r for r in scn["reqs"].values() if r["usable"]]
    if not usable:
        return False
    key = rng.choice(usable)["reserve_key"]
    scn["auth"]["reserves"][key] = (scn["gov"] + "-alt", scn["auth"]["reserves"][key][1])
    return True


def _members(scn, kind):
    P = oracle.prelim(scn)
    groups: dict[str, list[str]] = {}
    for pid, kinds in P["assign"].items():
        if kinds.get(kind):
            groups.setdefault(kinds[kind], []).append(pid)
    return P, groups


def m_zero_alloc_mass(scn, rng):
    """One member of a shared setup pool has allocation mass 0."""
    P, groups = _members(scn, "setup_pool")
    multi = [pids for pids in groups.values() if len({P["mat"][p]["num"] for p in pids}) > 1]
    if not multi:
        return False
    P["mat"][rng.choice(rng.choice(multi))]["alloc_g"] = D(0)
    return True


def m_pool_method(scn, rng):
    """The pool mail names another cent-allocation rule than largest remainders."""
    P, groups = _members(scn, "setup_pool")
    keys = [k for k, pids in groups.items() if len(pids) > 1 and k in scn["auth"]["pools"]]
    if not keys:
        return False
    key = rng.choice(keys)
    scn["auth"]["pools"][key] = (scn["auth"]["pools"][key][0],
                                 rng.choice(["remainder_to_first", "remainder_to_last", "remainder_to_largest"]))
    return True


def m_subcent_pool_fee(scn, rng):
    """A pool fee with a fraction of a cent."""
    P, groups = _members(scn, "setup_pool")
    keys = [k for k in groups if k in scn["auth"]["pools"]]
    if not keys:
        return False
    key = rng.choice(keys)
    fee, method = scn["auth"]["pools"][key]
    scn["auth"]["pools"][key] = (fee + rng.choice([D("0.005"), D("0.006"), D("0.009")]), method)
    return True


def _unknown_key(kind, store):
    def mutate(scn, rng):
        P, groups = _members(scn, kind)
        keys = [k for k in groups if k in scn["auth"][store]]
        if not keys:
            return False
        del scn["auth"][store][rng.choice(keys)]
        return True
    mutate.__doc__ = f"A Q&A-assigned {kind} key has no authorised record."
    return mutate


def m_mounting_punctuation(scn, rng):
    """The matching material writes the mounting with different punctuation ("Flansch-vorn")."""
    _, matched = _matched(scn)
    cands = [m for m in matched.values() if " " in m["mounting"].strip()]
    if not cands:
        return False
    m = rng.choice(cands)
    m["mounting"] = "-".join(m["mounting"].split())
    return True


def m_cert_synonym(scn, rng):
    """"No certificate" spelled a way only the new module lists ("n/a", "Nicht erforderlich", "Keine.")."""
    _, matched = _matched(scn)
    cands = [m for m in matched.values() if oracle.norm_cert(m["cert"]) == ""]
    if not cands:
        return False
    rng.choice(cands)["cert"] = rng.choice(["n/a", "Nicht erforderlich", "Keine.", "entfällt", "kein"])
    return True


def _rename_positions(scn, mapping):
    for p in scn["positions"]:
        p["id"] = mapping[p["id"]]
    for a in scn["qa"]:
        a["qty"] = [(mapping.get(pos, pos), q, unit) for pos, q, unit in a["qty"]]
        a["assign"] = {mapping.get(pos, pos): kinds for pos, kinds in a["assign"].items()}
        a["fees"] = {mapping.get(pos, pos): fee for pos, fee in a["fees"].items()}


def m_mixed_width_ids(scn, rng):
    """Position numbers of mixed width ("9", "10"): text order and numeric order disagree."""
    ids = sorted((p["id"] for p in scn["positions"]), key=oracle.idkey)
    start = 10 - rng.randint(1, len(ids) - 1)
    _rename_positions(scn, {old: str(start + i) for i, old in enumerate(ids)})
    return True


def m_multi_withdraw(scn, rng):
    """One answer withdraws two earlier answers."""
    live = sorted((a for a in scn["qa"] if a["when"] <= scn["t0"]), key=lambda a: a["when"])
    if len(live) < 3:
        return False
    live[-1]["withdraws"] = [a["num"] for a in rng.sample(live[:-1], 2)]
    return True


def m_withdraw_chain(scn, rng):
    """An answer withdraws an answer that itself withdrew a third (does the third come back?)."""
    live = sorted((a for a in scn["qa"] if a["when"] <= scn["t0"]), key=lambda a: a["when"])
    withdrawers = [a for a in live if a["withdraws"]]
    if not withdrawers:
        return False
    target = rng.choice(withdrawers)
    extra = blank_answer()
    extra.update(num=str(len(scn["qa"]) + 1), when=scn["t0"], withdraws=[target["num"]])
    scn["qa"].append(extra)
    return True


def m_withdraw_later(scn, rng):
    """An answer names a LATER answer as withdrawn (the rule text only speaks of earlier ones)."""
    live = sorted((a for a in scn["qa"] if a["when"] <= scn["t0"]), key=lambda a: a["when"])
    if len(live) < 2:
        return False
    i = rng.randrange(len(live) - 1)
    live[i]["withdraws"] = [rng.choice(live[i + 1:])["num"]]
    return True


def m_withdrawn_carries_more(scn, rng):
    """A withdrawn answer also carried an assignment, a fee or an amendment."""
    live = sorted((a for a in scn["qa"] if a["when"] <= scn["t0"]), key=lambda a: a["when"])
    cands = [a for a in live[:-1] if a["assign"] or a["fees"] or a["amend"]]
    if not cands:
        return False
    target = rng.choice(cands)
    if not target["qty"]:
        p = rng.choice(scn["positions"])
        target["qty"].append((p["id"], p["qty"] + 7, None))
    live[-1]["withdraws"] = [target["num"]]
    return True


def m_missing_requirement(scn, rng):
    """A position references a requirement the extraction did not deliver."""
    rng.choice(scn["positions"])["req"] = "AF-99"
    return True


def m_set_size_unknown(scn, rng):
    """A position counted in sets whose requirement has no pieces-per-set."""
    P = oracle.prelim(scn)
    cur = {p["id"]: p["unit"] for p in scn["positions"]}
    for a in P["live"]:
        for pos, _q, unit in a["qty"]:
            cur[pos] = unit or cur[pos]
    sets = [p for p in scn["positions"] if cur[p["id"]] == "Satz"]
    if not sets:
        return False
    scn["reqs"][rng.choice(sets)["req"]]["pps"] = None
    return True


def m_unassign_empty(scn, rng):
    """A later answer assigns an empty key (takes a position out of a group again)."""
    P = oracle.prelim(scn)
    cands = [(pid, kind) for pid, kinds in P["assign"].items() for kind in kinds]
    if not cands:
        return False
    pid, kind = rng.choice(cands)
    extra = blank_answer()
    extra.update(num=str(len(scn["qa"]) + 1), when=scn["t0"], assign={pid: {kind: ""}})
    scn["qa"].append(extra)
    return True


def m_revision_label_spelling(scn, rng):
    """An amendment names the governing revision with different punctuation ("Rev. C" for "Rev C")."""
    P = oracle.prelim(scn)
    live = [a for a in P["live"] if any(oracle.norm_txt(x[0]) == oracle.norm_txt(scn["gov"]) for x in a["amend"])]
    if not live:
        return False
    old_gov = scn["gov"]
    scn["gov"] = "Rev " + old_gov
    for a in scn["qa"]:
        a["amend"] = [(("Rev. " + old_gov) if oracle.norm_txt(rev) == oracle.norm_txt(old_gov) else rev, ref, attr, val)
                      for rev, ref, attr, val in a["amend"]]
    scn["auth"]["reserves"] = {k: ((scn["gov"] if rev == old_gov else rev), mm)
                               for k, (rev, mm) in scn["auth"]["reserves"].items()}
    return True


def m_revision_label_collapse(scn, rng):
    """Governing revision "1.0", an amendment for the superseded revision "10"."""
    old_gov = scn["gov"]
    others = {x[0] for a in scn["qa"] for x in a["amend"] if oracle.norm_txt(x[0]) != oracle.norm_txt(old_gov)}
    P = oracle.prelim(scn)
    live_other = {x[0] for a in P["live"] for x in a["amend"] if x[0] in others}
    if not live_other:
        return False
    victim = rng.choice(sorted(live_other))
    scn["gov"] = "1.0"
    for a in scn["qa"]:
        a["amend"] = [("1.0" if rev == old_gov else "10" if rev == victim else rev, ref, attr, val)
                      for rev, ref, attr, val in a["amend"]]
    scn["auth"]["reserves"] = {k: (("1.0" if rev == old_gov else rev), mm)
                               for k, (rev, mm) in scn["auth"]["reserves"].items()}
    return True


def m_german_attribute_name(scn, rng):
    """An amendment names its attribute in German ("Hub", "Bohrung", ...)."""
    P = oracle.prelim(scn)
    names = {"stroke": "Hub", "bore": "Bohrung", "pressure": "Druck", "mounting": "Befestigung",
             "certification": "Zertifizierung"}
    hit = False
    for a in P["live"]:
        if any(oracle.norm_txt(x[0]) == oracle.norm_txt(scn["gov"]) for x in a["amend"]):
            a["amend"] = [(rev, ref, names.get(attr, attr), val) for rev, ref, attr, val in a["amend"]]
            hit = True
    return hit


def m_same_time_answers(scn, rng):
    """Answers 9 and 10 carry the same timestamp and both change one position's quantity."""
    p = rng.choice(scn["positions"])
    for num, qty in (("9", p["qty"] + 3), ("10", p["qty"] + 11)):
        extra = blank_answer()
        extra.update(num=num, when=scn["t0"], qty=[(p["id"], qty, None)])
        scn["qa"] = [a for a in scn["qa"] if a["num"] != num] + [extra]
    for a in scn["qa"]:
        a["withdraws"] = [w for w in a["withdraws"] if w not in ("9", "10")]
    return True


def m_quantity_zero(scn, rng):
    """The latest answer sets a position's quantity to zero."""
    p = rng.choice(scn["positions"])
    extra = blank_answer()
    extra.update(num=str(len(scn["qa"]) + 1), when=scn["t0"], qty=[(p["id"], 0, None)])
    scn["qa"].append(extra)
    return True


def m_commitment_material_spelling(scn, rng):
    """The commitment names its material in lower case."""
    P = oracle.prelim(scn)
    keys = {kinds["delivery_commitment"] for kinds in P["assign"].values() if kinds.get("delivery_commitment")}
    keys = [k for k in keys if k in scn["auth"]["commit"]]
    if not keys:
        return False
    c = scn["auth"]["commit"][rng.choice(keys)]
    c["mat"] = c["mat"].lower()
    return True


def m_two_valid_conditions(scn, rng):
    """Two conditions are valid on the scenario date (the rule text assumes one)."""
    _, matched = _matched(scn)
    m = rng.choice(list(matched.values()))
    c = copy.deepcopy(_valid_cond(m, scn))
    c["scales"] = [(t, price + D("7.77")) for t, price in c["scales"]]
    m["conds"].insert(rng.randrange(len(m["conds"]) + 1), c)
    return True


MUTATIONS = {
    "fx_missing": m_fx_missing,
    "no_index_code": m_no_index_code,
    "index_missing": m_index_missing,
    "no_valid_condition": m_no_valid_condition,
    "below_lowest_scale": m_below_lowest_scale,
    "no_material": m_no_material,
    "no_material_unflagged": m_no_material_unflagged,
    "reserve_missing": m_reserve_missing,
    "reserve_wrong_revision": m_reserve_wrong_revision,
    "zero_alloc_mass": m_zero_alloc_mass,
    "pool_method": m_pool_method,
    "subcent_pool_fee": m_subcent_pool_fee,
    "unknown_tariff_key": _unknown_key("packaging_tariff", "tariffs"),
    "unknown_pool_key": _unknown_key("setup_pool", "pools"),
    "unknown_bonus_key": _unknown_key("project_bonus", "bonus"),
    "unknown_commitment_key": _unknown_key("delivery_commitment", "commit"),
    "unknown_clause_key": _unknown_key("condition_group", "clauses"),
    "mounting_punctuation": m_mounting_punctuation,
    "cert_synonym": m_cert_synonym,
    "mixed_width_ids": m_mixed_width_ids,
    "multi_withdraw": m_multi_withdraw,
    "withdraw_chain": m_withdraw_chain,
    "withdraw_later": m_withdraw_later,
    "withdrawn_carries_more": m_withdrawn_carries_more,
    "missing_requirement": m_missing_requirement,
    "set_size_unknown": m_set_size_unknown,
    "unassign_empty": m_unassign_empty,
    "revision_label_spelling": m_revision_label_spelling,
    "revision_label_collapse": m_revision_label_collapse,
    "german_attribute_name": m_german_attribute_name,
    "same_time_answers": m_same_time_answers,
    "quantity_zero": m_quantity_zero,
    "commitment_material_spelling": m_commitment_material_spelling,
    "two_valid_conditions": m_two_valid_conditions,
}


def mutate(scn, name, seed):
    out = copy.deepcopy(scn)
    rng = random.Random(f"{name}:{seed}")
    try:
        applied = MUTATIONS[name](out, rng)
    except (IndexError, KeyError, ValueError, TypeError):
        return None
    if not applied:
        return None
    out["mutation"] = name
    return out

