"""Differential test of starter-kit/calculator.py (NEW) against its predecessor (OLD), with a rule-text oracle.

    python -B harness.py --seeds 4000            # clean scenarios plus every mutation of each
    python -B harness.py --seeds 4000 --clean    # clean scenarios only
    python -B harness.py --seeds 500 --only fx_missing,pool_method
    python -B harness.py --replay 1234 [--mutation fx_missing]   # print one scenario and the three results

Reads both calculators by path (see adapters.py); writes nothing outside this directory.
"""
from __future__ import annotations

import argparse
import copy
import sys
import time
import traceback
from collections import Counter, defaultdict
from datetime import datetime
from decimal import Decimal

sys.dont_write_bytecode = True

import adapters  # noqa: E402
import neutral  # noqa: E402
import oracle  # noqa: E402
from adapters import FIELDS  # noqa: E402
from oracle import UNDET  # noqa: E402


# ----------------------------------------------------------------------------------------------------------------
# Comparison
# ----------------------------------------------------------------------------------------------------------------

def why_omitted(res, pid) -> str:
    for note in res["notes"]:
        if note.startswith(f"position {pid}:"):
            for needle, tag in (("no price condition", "no_valid_condition"), ("below the lowest", "below_lowest_scale"),
                                ("no FX", "fx_missing"), ("set size", "set_size"),
                                ("no material resolved", "unresolved_requirement_or_material")):
                if needle in note:
                    return tag
            return "other"
    return "?"


def pair_tokens(a, b) -> set[str]:
    """What differs between OLD (a) and NEW (b)."""
    out: set[str] = set()
    if a["error"] or b["error"]:
        if a["error"]:
            out.add("old_raises:" + a["error"].split(":")[0])
        if b["error"]:
            out.add("new_raises:" + b["error"].split(":")[0])
        return out
    if a["decision"] != b["decision"]:
        out.add(f"decision:old={a['decision']},new={b['decision']}")
    if a["discount"] != b["discount"]:
        out.add("discount@no_bid" if "no_bid" in (a["decision"], b["decision"]) else "discount")
    if a["decision"] == b["decision"] == "bid":
        for pid in set(a["lines"]) | set(b["lines"]):
            if pid not in b["lines"]:
                out.add("new_omits:" + why_omitted(b, pid))
                continue
            if pid not in a["lines"]:
                out.add("old_omits")
                continue
            for f in FIELDS:
                x, y = a["lines"][pid][f], b["lines"][pid][f]
                if y is None and x is not None:
                    out.add(f + ":new=None")
                elif x is None and y is not None:
                    out.add(f + ":old=None")
                elif x != y:
                    out.add(f)
        if a["total"] != b["total"]:
            out.add("total")
    return out


def oracle_tokens(o, r, who) -> tuple[set[str], set[str]]:
    """Where a calculator contradicts the rule-text oracle, and where it answers what the oracle leaves open."""
    out: set[str] = set()
    guesses: set[str] = set()
    if o["error"]:
        return {"oracle_undefined"}, guesses
    if r["error"]:
        return {f"{who}_raises:" + r["error"].split(":")[0]}, guesses
    if o["decision"] != r["decision"]:
        out.add(f"decision:rule={o['decision']},{who}={r['decision']}")
    if o["discount"] is UNDET:
        guesses.add("discount")
    elif o["discount"] != r["discount"]:
        out.add("discount@no_bid" if "no_bid" in (o["decision"], r["decision"]) else "discount")
    if o["decision"] == r["decision"] == "bid":
        for pid in set(o["lines"]) | set(r["lines"]):
            if pid not in r["lines"]:
                if pid in o["lines"]:
                    out.add(f"{who}_omits:" + (why_omitted(r, pid) if who == "new" else "?"))
                continue
            if pid not in o["lines"]:
                guesses.add("prices_position_without_evidence:" + str(o["omitted"].get(pid)))
                continue
            for f in FIELDS:
                x, y = o["lines"][pid][f], r["lines"][pid][f]
                if x is UNDET:
                    if y is not None:
                        guesses.add(f)
                    continue
                if y is None:
                    out.add(f"{f}:{who}=None")
                elif x != y:
                    out.add(f)
        if o["total"] is not UNDET and set(o["lines"]) == set(r["lines"]) and o["total"] != r["total"]:
            out.add("total")
    return out, guesses


def key_of(tokens: set[str]) -> tuple[str, ...]:
    rest = tokens - {"total"}
    return tuple(sorted(rest or tokens))


def evaluate(scn) -> dict:
    old, new = adapters.run_old(scn), adapters.run_new(scn)
    try:
        orc = oracle.solve(scn)
    except Exception as exc:  # noqa: BLE001 - the rule text has no answer for this input
        orc = {"error": type(exc).__name__, "decision": None, "discount": None, "total": None, "lines": {}, "omitted": {}}
    pt = pair_tokens(old, new)
    ot, _ = oracle_tokens(orc, old, "old")
    nt, ng = oracle_tokens(orc, new, "new")
    if orc["error"]:
        verdict = "oracle undefined"
    elif ot and not nt:
        verdict = "NEW matches rule text"
    elif nt and not ot:
        verdict = "OLD matches rule text"
    elif not nt and not ot:
        verdict = "rule text leaves it open"
    else:
        verdict = "NEITHER matches rule text"
    return {"old": old, "new": new, "orc": orc, "pt": pt, "ot": ot, "nt": nt, "ng": ng, "verdict": verdict}


def bucket_of(ev, mutation):
    if ev["pt"]:
        return ("DIFF", mutation, key_of(ev["pt"]), ev["verdict"])
    if ev["nt"] and ev["nt"] != {"oracle_undefined"}:
        return ("BOTH-vs-RULE", mutation, key_of(ev["nt"]), "old and new agree, both contradict the rule text")
    return None


# ----------------------------------------------------------------------------------------------------------------
# Shrinking
# ----------------------------------------------------------------------------------------------------------------

def reductions(s):
    ops = []
    n = len(s["positions"])
    ops += [("pos", i) for i in range(n) if n > 1]
    ops += [("qa", i) for i in range(len(s["qa"]))]
    for i, a in enumerate(s["qa"]):
        ops += [("qa_qty", i, j) for j in range(len(a["qty"]))]
        ops += [("qa_amend", i, j) for j in range(len(a["amend"]))]
        ops += [("qa_assign", i, pos, kind) for pos in a["assign"] for kind in a["assign"][pos]]
        ops += [("qa_fee", i, pos) for pos in a["fees"]]
        ops += [("qa_wd", i, j) for j in range(len(a["withdraws"]))]
    for i, m in enumerate(s["mats"]):
        ops.append(("mat", i))
        for j, c in enumerate(m["conds"]):
            ops.append(("cond", i, j))
            ops += [("scale", i, j, k) for k in range(len(c["scales"])) if len(c["scales"]) > 1]
    used = {p["req"] for p in s["positions"]}
    ops += [("req", ref) for ref in s["reqs"] if ref not in used]
    for store in ("clauses", "index_kg", "reserves", "tariffs", "commit", "fx", "pools", "bonus"):
        ops += [("auth", store, k) for k in s["auth"][store]]
    for k, bands in s["auth"]["bonus"].items():
        ops += [("band", k, j) for j in range(len(bands)) if len(bands) > 1]
    if s["auth"]["min_order"] is not None:
        ops.append(("min_order",))
    if s["auth"]["disc"] is not None:
        ops.append(("disc",))
    ops += [("unit_stk", i) for i, p in enumerate(s["positions"]) if p["unit"] == "Satz"]
    ops += [("not_usable", ref) for ref, r in s["reqs"].items() if r["usable"]]
    for i, m in enumerate(s["mats"]):
        if m["sur_g"]:
            ops.append(("sur0", i))
        if m["index"]:
            ops.append(("noindex", i))
        if m["carton"] != 1:
            ops.append(("carton1", i))
        for j, c in enumerate(m["conds"]):
            if c["pu"] != 1:
                ops.append(("pu1", i, j))
            if c["cur"] != "EUR":
                ops.append(("eur", i, j))
    return ops


def apply(s, op):
    s = copy.deepcopy(s)
    kind = op[0]
    if kind == "pos":
        pid = s["positions"].pop(op[1])["id"]
        for a in s["qa"]:
            a["qty"] = [x for x in a["qty"] if x[0] != pid]
            a["assign"].pop(pid, None)
            a["fees"].pop(pid, None)
    elif kind == "qa":
        num = s["qa"].pop(op[1])["num"]
        for a in s["qa"]:
            a["withdraws"] = [w for w in a["withdraws"] if w != num]
    elif kind == "qa_qty":
        s["qa"][op[1]]["qty"].pop(op[2])
    elif kind == "qa_amend":
        s["qa"][op[1]]["amend"].pop(op[2])
    elif kind == "qa_assign":
        entry = s["qa"][op[1]]["assign"]
        del entry[op[2]][op[3]]
        if not entry[op[2]]:
            del entry[op[2]]
    elif kind == "qa_fee":
        del s["qa"][op[1]]["fees"][op[2]]
    elif kind == "qa_wd":
        s["qa"][op[1]]["withdraws"].pop(op[2])
    elif kind == "mat":
        s["mats"].pop(op[1])
    elif kind == "cond":
        s["mats"][op[1]]["conds"].pop(op[2])
    elif kind == "scale":
        s["mats"][op[1]]["conds"][op[2]]["scales"].pop(op[3])
    elif kind == "req":
        del s["reqs"][op[1]]
    elif kind == "auth":
        del s["auth"][op[1]][op[2]]
    elif kind == "band":
        s["auth"]["bonus"][op[1]].pop(op[2])
    elif kind == "min_order":
        s["auth"]["min_order"] = None
    elif kind == "disc":
        s["auth"]["disc"] = None
    elif kind == "unit_stk":
        s["positions"][op[1]]["unit"] = "Stk"
    elif kind == "not_usable":
        s["reqs"][op[1]]["usable"] = False
    elif kind == "sur0":
        s["mats"][op[1]]["sur_g"] = Decimal(0)
    elif kind == "noindex":
        s["mats"][op[1]]["index"] = None
    elif kind == "carton1":
        s["mats"][op[1]]["carton"] = 1
    elif kind == "pu1":
        s["mats"][op[1]]["conds"][op[2]]["pu"] = 1
    elif kind == "eur":
        s["mats"][op[1]]["conds"][op[2]].update(cur="EUR", fx=None)
    return s


def shrink(scn, mutation, target, budget=4000):
    spent = 0
    changed = True
    while changed and spent < budget:
        changed = False
        for op in reversed(reductions(scn)):
            try:
                cand = apply(scn, op)
            except (IndexError, KeyError):
                continue
            spent += 1
            if bucket_of(evaluate(cand), mutation) == target:
                scn, changed = cand, True
    return scn


# ----------------------------------------------------------------------------------------------------------------
# Printing a scenario as NEW-API constructor calls
# ----------------------------------------------------------------------------------------------------------------

def py(v) -> str:
    if isinstance(v, bool) or v is None:
        return repr(v)
    if isinstance(v, Decimal):
        return f'Decimal("{v}")'
    if isinstance(v, datetime):
        parts = [v.year, v.month, v.day, v.hour, v.minute]
        if v.second or v.microsecond:
            parts.append(v.second)
        if v.microsecond:
            parts.append(v.microsecond)
        return "datetime(" + ", ".join(map(str, parts)) + ", tzinfo=UTC)"
    if isinstance(v, tuple):
        return "(" + ", ".join(py(x) for x in v) + ("," if len(v) == 1 else "") + ")"
    if isinstance(v, list):
        return "[" + ", ".join(py(x) for x in v) + "]"
    if isinstance(v, set):
        return "{" + ", ".join(py(x) for x in sorted(v)) + "}" if v else "set()"
    if isinstance(v, dict):
        return "{" + ", ".join(f"{py(k)}: {py(x)}" for k, x in v.items()) + "}"
    return repr(v)


def emit_new(s) -> str:
    out = ["bid = calculate_bid(", f"    {py(s['ref'])}, {py(s['t0'])}, {py(s['gov'])},", "    positions=["]
    out += [f"        Position({py(p['id'])}, {py(p['req'])}, {p['qty']}, is_set={p['unit'] == 'Satz'}),"
            for p in s["positions"]]
    out += ["    ],", "    clarifications=["]
    for a in s["qa"]:
        args = [py(a["num"]), py(a["when"])]
        if a["withdraws"]:
            args.append("withdraws=" + py(list(a["withdraws"])))
        if a["qty"]:
            args.append("quantity_changes=" + py([(pos, q, None if unit is None else unit == "Satz") for pos, q, unit in a["qty"]]))
        if a["amend"]:
            args.append("amendments=" + py([tuple(x) for x in a["amend"]]))
        if a["assign"]:
            args.append("assignments=" + py(a["assign"]))
        if a["fees"]:
            args.append("setup_fees=" + py(a["fees"]))
        out.append("        Clarification(" + ", ".join(args) + "),")
    out += ["    ],", "    requirements={"]
    for ref, r in s["reqs"].items():
        out.append(f"        {py(ref)}: Requirement({py(ref)}, bore_mm={r['bore']}, stroke_mm={r['stroke']}, "
                   f"pressure_bar={r['pressure']}, mounting={py(r['mounting'])}, certification={py(r['cert'])}, "
                   f"catalogue_group={py(r['group'])}, usable_travel={r['usable']}, reserve_key={py(r['reserve_key'])}, "
                   f"pieces_per_set={py(r['pps'])}),")
    out += ["    },", "    materials=["]
    for m in s["mats"]:
        conds = ", ".join(f"PriceCondition({py(c['from'])}, {py(c['to'])}, {py(c['cur'])}, {py(c['fx'])}, {c['pu']}, "
                          f"{py([tuple(x) for x in c['scales']])})" for c in m["conds"])
        out.append(f"        Material({py(m['num'])}, active={m['active']}, catalogue_group={py(m['group'])}, "
                   f"bore_mm={m['bore']}, stroke_mm={m['stroke']}, pressure_bar={m['pressure']}, "
                   f"mounting={py(m['mounting'])}, certification={py(m['cert'])}, carton_size={py(m['carton'])}, "
                   f"allocation_mass_g={py(m['alloc_g'])}, surcharge_mass_g={py(m['sur_g'])}, "
                   f"index_code={py(m['index'])}, stock={py(m['stock'])}, stock_lead_weeks={py(m['stock_lead'])}, "
                   f"production_lead_weeks={py(m['prod_lead'])}, conditions=[{conds}]),")
    a = s["auth"]
    out += ["    ],", "    authorities=Authorities("]
    out.append(f"        discount_percent={py(a['disc'])}, discount_min_order={py(a['min_order'])},")
    if a["clauses"]:
        out.append(f"        clauses={py(a['clauses'])},")
    if a["index_kg"]:
        out.append(f"        index_rates={py({k: v / Decimal(1000) for k, v in a['index_kg'].items()})},  # EUR per gram")
    if a["reserves"]:
        out.append(f"        reserves={py(a['reserves'])},")
    if a["tariffs"]:
        out.append(f"        tariffs={py(a['tariffs'])},")
    if a["commit"]:
        inner = ", ".join(f"{py(k)}: Commitment({py(c['mat'])}, {c['weeks']}, {c['max']})" for k, c in a["commit"].items())
        out.append("        commitments={" + inner + "},")
    if a["fx"]:
        out.append(f"        fx={py(a['fx'])},")
    if a["pools"]:
        out.append(f"        pools={py(a['pools'])},")
    if a["bonus"]:
        inner = ", ".join(f"{py(k)}: [" + ", ".join(f"BonusBand({py(lo)}, {py(up)}, {py(pct)})" for lo, up, pct in bands) + "]"
                          for k, bands in a["bonus"].items())
        out.append("        bonus={" + inner + "},")
    out.append("    ),")
    flag = s.get("no_material", "all")
    names = sorted(set(s["reqs"]) | {p["req"] for p in s["positions"]}) if flag == "all" else flag
    out.append(f"    no_material={py(set(names)) if names is not None else None},")
    out.append(")")
    return "\n".join(out)


def show(res, label) -> str:
    if res.get("error"):
        return f"  {label}: raises {res['error']}"
    head = f"  {label}: decision={res['decision']} discount={res['discount']} total={res['total']}"
    omitted = res.get("omitted")
    if omitted:
        head += f" omitted={dict(omitted) if isinstance(omitted, dict) else list(omitted)}"
    rows = [head]
    for pid in sorted(res["lines"], key=oracle.idkey):
        line = res["lines"][pid]
        rows.append(f"      pos {pid}: " + " ".join(f"{f.replace('_per_unit', '').replace('_unit_price', '')}={line[f]}"
                                                    for f in FIELDS))
    for note in res.get("notes") or []:
        rows.append(f"      note: {note}")
    return "\n".join(rows)


# ----------------------------------------------------------------------------------------------------------------
# Boundary coverage of the clean generator
# ----------------------------------------------------------------------------------------------------------------

def coverage(scn, counter: Counter) -> None:
    P = oracle.prelim(scn)
    auth = scn["auth"]
    ids = [p["id"] for p in scn["positions"]]
    demand: Counter = Counter()
    for pid in ids:
        demand[P["mat"][pid]["num"]] += P["qty"][pid]
    mats = {P["mat"][pid]["num"]: P["mat"][pid] for pid in ids}
    conds = {pid: next(c for c in P["mat"][pid]["conds"] if c["from"] <= scn["t0"] <= c["to"]) for pid in ids}
    goods = {pid: Decimal(P["qty"][pid]) * P["base"][pid] for pid in ids}
    order_value = sum(goods.values(), Decimal(0))

    def hit(name, cond):
        if cond:
            counter[name] += 1

    hit("quantity exactly on a scale > 1", any(any(t == P["qty"][pid] and t > 1 for t, _ in conds[pid]["scales"]) for pid in ids))
    hit("quantity one below a scale", any(any(t == P["qty"][pid] + 1 for t, _ in conds[pid]["scales"]) for pid in ids))
    hit("stock == pooled demand", any(m["stock"] == demand[num] for num, m in mats.items()))
    hit("stock == pooled demand - 1", any(m["stock"] == demand[num] - 1 for num, m in mats.items()))
    hit("stock covers one position but not the pooled sum", any(
        P["qty"][pid] <= P["mat"][pid]["stock"] < demand[P["mat"][pid]["num"]] for pid in ids))
    hit("material shared by 2+ positions", any(sum(1 for pid in ids if P["mat"][pid]["num"] == num) > 1 for num in mats))
    hit("order value == discount threshold", auth["disc"] and auth["min_order"] == order_value)
    hit("order value one cent below threshold", auth["disc"] and auth["min_order"] == order_value + Decimal("0.01"))
    commits = [(pid, auth["commit"].get(P["assign"].get(pid, {}).get("delivery_commitment"))) for pid in ids]
    hit("commitment ceiling == pooled demand", any(c and c["mat"] == P["mat"][pid]["num"] and c["max"] == demand[c["mat"]] for pid, c in commits))
    hit("commitment ceiling == pooled demand - 1", any(c and c["mat"] == P["mat"][pid]["num"] and c["max"] == demand[c["mat"]] - 1 for pid, c in commits))
    hit("commitment for another material", any(c and c["mat"] != P["mat"][pid]["num"] for pid, c in commits))
    for key, bands in auth["bonus"].items():
        members = [pid for pid in ids if P["assign"].get(pid, {}).get("project_bonus") == key]
        if members:
            eligible = sum((goods[pid] for pid in members), Decimal(0))
            hit("bonus total exactly on a band edge", any(eligible in (lo, up) for lo, up, _ in bands))
            counter["scenarios with a project bonus"] += 1
    hit("valid-from or valid-to == scenario instant", any(scn["t0"] in (c["from"], c["to"]) for c in conds.values()))
    hit("price unit != 1", any(c["pu"] != 1 for c in conds.values()))
    hit("non-EUR condition", any(c["cur"] != "EUR" for c in conds.values()))
    hit("Satz position", any(p["unit"] == "Satz" for p in scn["positions"]))
    hit("usable-travel requirement", any(P["reqs"][p["req"]]["usable"] for p in scn["positions"]))
    live = {a["num"] for a in P["live"]}
    hit("answer dated after the scenario", any(a["when"] > scn["t0"] for a in scn["qa"]))
    hit("answer dated exactly at the scenario instant", any(a["when"] == scn["t0"] for a in scn["qa"]))
    hit("effective withdrawal", any(a["when"] <= scn["t0"] and a["num"] not in live for a in scn["qa"]))
    hit("amendment for the governing revision", any(x[0] == scn["gov"] for a in P["live"] for x in a["amend"]))
    hit("amendment for another revision", any(x[0] != scn["gov"] for a in P["live"] for x in a["amend"]))
    hit("setup pool with 2+ members", any(sum(1 for pid in ids if P["assign"].get(pid, {}).get("setup_pool") == k) > 1 for k in auth["pools"]))


# ----------------------------------------------------------------------------------------------------------------

def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--seeds", type=int, default=2000)
    ap.add_argument("--start", type=int, default=0)
    ap.add_argument("--clean", action="store_true", help="clean scenarios only")
    ap.add_argument("--only", default="", help="comma-separated mutation names")
    ap.add_argument("--replay", type=int, default=None)
    ap.add_argument("--mutation", default=None)
    ap.add_argument("--no-shrink", action="store_true")
    ap.add_argument("--examples", type=int, default=1, help="shrunk examples printed per bucket")
    args = ap.parse_args()

    print(f"NEW  {adapters.NEW_PATH}  sha256[:16]={adapters.NEW_HASH}")
    print(f"OLD  {adapters.OLD_PATH}  sha256[:16]={adapters.OLD_HASH}")

    if args.replay is not None:
        scn = neutral.gen_clean(args.replay)
        if args.mutation:
            scn = neutral.mutate(scn, args.mutation, args.replay)
            if scn is None:
                print("mutation did not apply to this seed")
                return
        ev = evaluate(scn)
        print("from datetime import datetime, timezone\nfrom decimal import Decimal\nfrom calculator import *\nUTC = timezone.utc\n")
        print(emit_new(scn))
        print(show(ev["old"], "OLD"), show(ev["new"], "NEW"), show(ev["orc"], "RULE"), sep="\n")
        print("old-vs-new:", sorted(ev["pt"]), "| new-vs-rule:", sorted(ev["nt"]), "| old-vs-rule:", sorted(ev["ot"]),
              "| verdict:", ev["verdict"], "| new answers what the rule text leaves open:", sorted(ev["ng"]))
        return

    names = [] if args.clean else ([n for n in args.only.split(",") if n] or list(neutral.MUTATIONS))
    runs, mismatches, both_wrong = Counter(), Counter(), Counter()
    buckets: dict = defaultdict(lambda: {"count": 0, "examples": []})
    guesses: dict = defaultdict(Counter)
    cover: Counter = Counter()
    gen_errors = 0
    started = time.time()

    def record(mutation, scn, seed):
        ev = evaluate(scn)
        runs[mutation] += 1
        mismatches[mutation] += bool(ev["pt"])
        both_wrong[mutation] += bool(not ev["pt"] and ev["nt"] and ev["nt"] != {"oracle_undefined"})
        for g in ev["ng"]:
            guesses[mutation][g.split(":")[0]] += 1
        b = bucket_of(ev, mutation)
        if b:
            entry = buckets[b]
            entry["count"] += 1
            size = len(scn["positions"]) + len(scn["qa"]) + len(scn["mats"])
            entry["examples"].append((size, seed, scn))
            entry["examples"] = sorted(entry["examples"], key=lambda e: e[:2])[:max(3, args.examples)]

    stats_before = dict(oracle.STATS)
    for seed in range(args.start, args.start + args.seeds):
        try:
            base = neutral.gen_clean(seed)
        except Exception:  # noqa: BLE001
            gen_errors += 1
            if gen_errors == 1:
                traceback.print_exc()
            continue
        before = dict(oracle.STATS)
        record("CLEAN", base, seed)
        cover["exact half cent met while rounding"] += oracle.STATS["half_cent"] > before["half_cent"]
        cover["largest-remainder tie on the last cent"] += oracle.STATS["alloc_tie"] > before["alloc_tie"]
        try:
            coverage(base, cover)
        except Exception:  # noqa: BLE001
            cover["coverage probe failed"] += 1
        for name in names:
            scn = neutral.mutate(base, name, seed)
            if scn is not None:
                record(name, scn, seed)

    elapsed = time.time() - started
    total_runs, total_mis = sum(runs.values()), sum(mismatches.values())
    print(f"\nseeds {args.start}..{args.start + args.seeds - 1}: {runs['CLEAN']} clean scenarios"
          f" ({gen_errors} generator errors), {total_runs} scenarios in all, {elapsed:.0f}s")
    print(f"old-vs-new mismatches: {total_mis}/{total_runs} = {100 * total_mis / max(1, total_runs):.2f}%")
    print(f"  clean scenarios:   {mismatches['CLEAN']}/{runs['CLEAN']} mismatch, "
          f"{both_wrong['CLEAN']} agree with each other but not with the rule-text oracle")
    print("\nper mutation: applied / old!=new / old==new but both != rule text")
    for name in names:
        print(f"  {name:32s} {runs[name]:6d} {mismatches[name]:6d} {both_wrong[name]:6d}")
    print("\nboundary coverage of the clean generator (scenarios with at least one such case):")
    for name, count in sorted(cover.items(), key=lambda kv: -kv[1]):
        print(f"  {count:6d}  {name}")
    print(f"  (oracle counters over the whole run: {dict((k, oracle.STATS[k] - stats_before[k]) for k in oracle.STATS)})")
    print("\nNEW answers fields the rule text leaves open on the given evidence (count of scenarios, by mutation):")
    for name in ["CLEAN"] + names:
        if guesses[name]:
            print(f"  {name:32s} " + ", ".join(f"{g}={c}" for g, c in guesses[name].most_common()))

    print("\n" + "=" * 118 + "\nBUCKETS\n" + "=" * 118)
    order = sorted(buckets.items(), key=lambda kv: (kv[0][0] != "DIFF", kv[0][1] != "CLEAN", kv[0][1], -kv[1]["count"]))
    for (kind, mutation, key, verdict), entry in order:
        doc = (neutral.MUTATIONS[mutation].__doc__ or "").strip() if mutation in neutral.MUTATIONS else "well-formed scenario"
        print(f"\n### [{kind}] {mutation}: {' + '.join(key)}")
        print(f"    count={entry['count']} of {runs[mutation]} | verdict: {verdict}")
        print(f"    hazard: {doc}")
        print(f"    seeds: {[e[1] for e in entry['examples']]}")
        if args.no_shrink:
            continue
        for _size, seed, scn in entry["examples"][:args.examples]:
            small = shrink(scn, mutation, (kind, mutation, key, verdict))
            ev = evaluate(small)
            print(f"    minimal scenario (from seed {seed}):")
            print("\n".join("    " + line for line in emit_new(small).splitlines()))
            print(show(ev["old"], "OLD"), show(ev["new"], "NEW"), show(ev["orc"], "RULE"), sep="\n")
            print(f"    new-vs-rule: {sorted(ev['nt'])} | old-vs-rule: {sorted(ev['ot'])} | open fields NEW answered: {sorted(ev['ng'])}")


if __name__ == "__main__":
    main()

toolu_01GVprCqjtxU9ffBQe7b6pXh.content:
"""Differential test of starter-kit/calculator.py (NEW) against its predecessor (OLD), with a rule-text oracle.

    python -B harness.py --seeds 4000            # clean scenarios plus every mutation of each
    python -B harness.py --seeds 4000 --clean    # clean scenarios only
    python -B harness.py --seeds 500 --only fx_missing,pool_method
    python -B harness.py --replay 1234 [--mutation fx_missing]   # print one scenario and the three results

Reads both calculators by path (see adapters.py); writes nothing outside this directory.
"""
from __future__ import annotations

import argparse
import copy
import sys
import time
import traceback
from collections import Counter, defaultdict
from datetime import datetime
from decimal import Decimal

sys.dont_write_bytecode = True

import adapters  # noqa: E402
import neutral  # noqa: E402
import oracle  # noqa: E402
from adapters import FIELDS  # noqa: E402
from oracle import UNDET  # noqa: E402


# ----------------------------------------------------------------------------------------------------------------
# Comparison
# ----------------------------------------------------------------------------------------------------------------

def why_omitted(res, pid) -> str:
    for note in res["notes"]:
        if note.startswith(f"position {pid}:"):
            for needle, tag in (("no price condition", "no_valid_condition"), ("below the lowest", "below_lowest_scale"),
                                ("no FX", "fx_missing"), ("set size", "set_size"),
                                ("no material resolved", "unresolved_requirement_or_material")):
                if needle in note:
                    return tag
            return "other"
    return "?"


def pair_tokens(a, b) -> set[str]:
    """What differs between OLD (a) and NEW (b)."""
    out: set[str] = set()
    if a["error"] or b["error"]:
        if a["error"]:
            out.add("old_raises:" + a["error"].split(":")[0])
        if b["error"]:
            out.add("new_raises:" + b["error"].split(":")[0])
        return out
    if a["decision"] != b["decision"]:
        out.add(f"decision:old={a['decision']},new={b['decision']}")
    if a["discount"] != b["discount"]:
        out.add("discount@no_bid" if "no_bid" in (a["decision"], b["decision"]) else "discount")
    if a["decision"] == b["decision"] == "bid":
        for pid in set(a["lines"]) | set(b["lines"]):
            if pid not in b["lines"]:
                out.add("new_omits:" + why_omitted(b, pid))
                continue
            if pid not in a["lines"]:
                out.add("old_omits")
                continue
            for f in FIELDS:
                x, y = a["lines"][pid][f], b["lines"][pid][f]
                if y is None and x is not None:
                    out.add(f + ":new=None")
                elif x is None and y is not None:
                    out.add(f + ":old=None")
                elif x != y:
                    out.add(f)
        if a["total"] != b["total"]:
            out.add("total")
    return out


def oracle_tokens(o, r, who) -> tuple[set[str], set[str]]:
    """Where a calculator contradicts the rule-text oracle, and where it answers what the oracle leaves open."""
    out: set[str] = set()
    guesses: set[str] = set()
    if o["error"]:
        return {"oracle_undefined"}, guesses
    if r["error"]:
        return {f"{who}_raises:" + r["error"].split(":")[0]}, guesses
    if o["decision"] != r["decision"]:
        out.add(f"decision:rule={o['decision']},{who}={r['decision']}")
    if o["discount"] is UNDET:
        guesses.add("discount")
    elif o["discount"] != r["discount"]:
        out.add("discount@no_bid" if "no_bid" in (o["decision"], r["decision"]) else "discount")
    if o["decision"] == r["decision"] == "bid":
        for pid in set(o["lines"]) | set(r["lines"]):
            if pid not in r["lines"]:
                if pid in o["lines"]:
                    out.add(f"{who}_omits:" + (why_omitted(r, pid) if who == "new" else "?"))
                continue
            if pid not in o["lines"]:
                guesses.add("prices_position_without_evidence:" + str(o["omitted"].get(pid)))
                continue
            for f in FIELDS:
                x, y = o["lines"][pid][f], r["lines"][pid][f]
                if x is UNDET:
                    if y is not None:
                        guesses.add(f)
                    continue
                if y is None:
                    out.add(f"{f}:{who}=None")
                elif x != y:
                    out.add(f)
        if o["total"] is not UNDET and set(o["lines"]) == set(r["lines"]) and o["total"] != r["total"]:
            out.add("total")
    return out, guesses


def key_of(tokens: set[str]) -> tuple[str, ...]:
    rest = tokens - {"total"}
    return tuple(sorted(rest or tokens))


def evaluate(scn) -> dict:
    old, new = adapters.run_old(scn), adapters.run_new(scn)
    try:
        orc = oracle.solve(scn)
    except Exception as exc:  # noqa: BLE001 - the rule text has no answer for this input
        orc = {"error": type(exc).__name__, "decision": None, "discount": None, "total": None, "lines": {}, "omitted": {}}
    pt = pair_tokens(old, new)
    ot, _ = oracle_tokens(orc, old, "old")
    nt, ng = oracle_tokens(orc, new, "new")
    if orc["error"]:
        verdict = "oracle undefined"
    elif ot and not nt:
        verdict = "NEW matches rule text"
    elif nt and not ot:
        verdict = "OLD matches rule text"
    elif not nt and not ot:
        verdict = "rule text leaves it open"
    else:
        verdict = "NEITHER matches rule text"
    return {"old": old, "new": new, "orc": orc, "pt": pt, "ot": ot, "nt": nt, "ng": ng, "verdict": verdict}


def bucket_of(ev, mutation):
    if ev["pt"]:
        return ("DIFF", mutation, key_of(ev["pt"]), ev["verdict"])
    if ev["nt"] and ev["nt"] != {"oracle_undefined"}:
        return ("BOTH-vs-RULE", mutation, key_of(ev["nt"]), "old and new agree, both contradict the rule text")
    return None


# ----------------------------------------------------------------------------------------------------------------
# Shrinking
# ----------------------------------------------------------------------------------------------------------------

def reductions(s):
    ops = []
    n = len(s["positions"])
    ops += [("pos", i) for i in range(n) if n > 1]
    ops += [("qa", i) for i in range(len(s["qa"]))]
    for i, a in enumerate(s["qa"]):
        ops += [("qa_qty", i, j) for j in range(len(a["qty"]))]
        ops += [("qa_amend", i, j) for j in range(len(a["amend"]))]
        ops += [("qa_assign", i, pos, kind) for pos in a["assign"] for kind in a["assign"][pos]]
        ops += [("qa_fee", i, pos) for pos in a["fees"]]
        ops += [("qa_wd", i, j) for j in range(len(a["withdraws"]))]
    for i, m in enumerate(s["mats"]):
        ops.append(("mat", i))
        for j, c in enumerate(m["conds"]):
            ops.append(("cond", i, j))
            ops += [("scale", i, j, k) for k in range(len(c["scales"])) if len(c["scales"]) > 1]
    used = {p["req"] for p in s["positions"]}
    ops += [("req", ref) for ref in s["reqs"] if ref not in used]
    for store in ("clauses", "index_kg", "reserves", "tariffs", "commit", "fx", "pools", "bonus"):
        ops += [("auth", store, k) for k in s["auth"][store]]
    for k, bands in s["auth"]["bonus"].items():
        ops += [("band", k, j) for j in range(len(bands)) if len(bands) > 1]
    if s["auth"]["min_order"] is not None:
        ops.append(("min_order",))
    if s["auth"]["disc"] is not None:
        ops.append(("disc",))
    ops += [("unit_stk", i) for i, p in enumerate(s["positions"]) if p["unit"] == "Satz"]
    ops += [("not_usable", ref) for ref, r in s["reqs"].items() if r["usable"]]
    for i, m in enumerate(s["mats"]):
        if m["sur_g"]:
            ops.append(("sur0", i))
        if m["index"]:
            ops.append(("noindex", i))
        if m["carton"] != 1:
            ops.append(("carton1", i))
        for j, c in enumerate(m["conds"]):
            if c["pu"] != 1:
                ops.append(("pu1", i, j))
            if c["cur"] != "EUR":
                ops.append(("eur", i, j))
    return ops


def apply(s, op):
    s = copy.deepcopy(s)
    kind = op[0]
    if kind == "pos":
        pid = s["positions"].pop(op[1])["id"]
        for a in s["qa"]:
            a["qty"] = [x for x in a["qty"] if x[0] != pid]
            a["assign"].pop(pid, None)
            a["fees"].pop(pid, None)
    elif kind == "qa":
        num = s["qa"].pop(op[1])["num"]
        for a in s["qa"]:
            a["withdraws"] = [w for w in a["withdraws"] if w != num]
    elif kind == "qa_qty":
        s["qa"][op[1]]["qty"].pop(op[2])
    elif kind == "qa_amend":
        s["qa"][op[1]]["amend"].pop(op[2])
    elif kind == "qa_assign":
        entry = s["qa"][op[1]]["assign"]
        del entry[op[2]][op[3]]
        if not entry[op[2]]:
            del entry[op[2]]
    elif kind == "qa_fee":
        del s["qa"][op[1]]["fees"][op[2]]
    elif kind == "qa_wd":
        s["qa"][op[1]]["withdraws"].pop(op[2])
    elif kind == "mat":
        s["mats"].pop(op[1])
    elif kind == "cond":
        s["mats"][op[1]]["conds"].pop(op[2])
    elif kind == "scale":
        s["mats"][op[1]]["conds"][op[2]]["scales"].pop(op[3])
    elif kind == "req":
        del s["reqs"][op[1]]
    elif kind == "auth":
        del s["auth"][op[1]][op[2]]
    elif kind == "band":
        s["auth"]["bonus"][op[1]].pop(op[2])
    elif kind == "min_order":
        s["auth"]["min_order"] = None
    elif kind == "disc":
        s["auth"]["disc"] = None
    elif kind == "unit_stk":
        s["positions"][op[1]]["unit"] = "Stk"
    elif kind == "not_usable":
        s["reqs"][op[1]]["usable"] = False
    elif kind == "sur0":
        s["mats"][op[1]]["sur_g"] = Decimal(0)
    elif kind == "noindex":
        s["mats"][op[1]]["index"] = None
    elif kind == "carton1":
        s["mats"][op[1]]["carton"] = 1
    elif kind == "pu1":
        s["mats"][op[1]]["conds"][op[2]]["pu"] = 1
    elif kind == "eur":
        s["mats"][op[1]]["conds"][op[2]].update(cur="EUR", fx=None)
    return s


def shrink(scn, mutation, target, budget=4000):
    spent = 0
    changed = True
    while changed and spent < budget:
        changed = False
        for op in reversed(reductions(scn)):
            try:
                cand = apply(scn, op)
            except (IndexError, KeyError):
                continue
            spent += 1
            if bucket_of(evaluate(cand), mutation) == target:
                scn, changed = cand, True
    return scn


