def primary(key: tuple[str, ...]) -> str:
    """The headline of a difference; what else differs in the same scenario is its knock-on effect."""
    if key == ("discount@no_bid",):
        return "discount on a no_bid"
    for prefix in ("old_raises", "new_raises", "decision:", "new_omits:", "old_omits"):
        hit = [t for t in key if t.startswith(prefix)]
        if hit:
            return hit[0]
    return "same positions, different values"


